mapper.select:
SELECT EXISTS( SELECT 1 FROM document_asset_extraction e JOIN document_asset a ON a.asset_id = e.asset_id AND a.document_id = e.document_id JOIN document d ON d.id = a.document_id WHERE e.status = 'ACTIVE' AND d.kb_id IN
CAST(#{kbId} AS uuid)
)

SELECT e.visual_kind AS visualKind, a.locator::text AS locator, e.caption AS caption, (SELECT string_agg(DISTINCT t.entity_type, ',') FROM document_asset_entity t WHERE t.extraction_id = e.extraction_id) AS entityTypes FROM document_asset_extraction e JOIN document_asset a ON a.asset_id = e.asset_id AND a.document_id = e.document_id JOIN document d ON d.id = a.document_id WHERE e.status = 'ACTIVE' AND d.kb_id IN
CAST(#{kbId} AS uuid)
ORDER BY e.updated_at DESC, e.extraction_id LIMIT #{limit}
